 * 4.12.1 — سرویس‌های خارجی: تولید متن (ai.text) بیرون — کلیدش در خلاصه‌ساز (خواستۀ
 *          کاربر)؛ ElevenLabs در صدای هوش مصنوعی؛ «+ ارائه‌دهندۀ دوم» برای سرویس‌های
 *          چندآداپتوری با بازگشت خودکار؛ چیدمان صفحه (ستون ثابت، فیلد تمام‌پهنا، حاشیه).
 *
 * 4.12.0 — SPRINT-4.4 فاز ۲ب. بخش ۱۹: بستۀ محتوای هر نوع پست (P5-D272).
 *
 *        — برون‌بری قالب هر نوع، ساخته از اسکیمای زندۀ جت‌انجین: فیلدهای
 *          متاباکس (کلید، برچسب، نوع، الزام، توضیح، واحد، کلاس WPML)،
 *          گزینه‌های واژه‌نامه، زیرفیلدهای Repeater، رابطه‌ها (شماره، نوع
 *          مقصد، جهت، کاردینالیتی) و کمینۀ واژۀ اسناد CA؛ JSON Schema از
 *          همان تعریف‌ها؛ بلوک دستور ثابت به زبان محتوا؛ برون‌بری پست موجود.
 *        — درون‌ریزی گسترش واردکنندۀ بخش ۱۴ (پرونده topersia-geo-import/2.0):
 *          گزارش آزمایشی فیلدبه‌فیلد، سپس «اجرا» دسته‌دسته با AJAX. پست تازه
 *          پیش‌نویس با needs_verification؛ تطبیق با entity_uid یا نامک در همان
 *          زبان؛ ترجمه با translation_of؛ یال با API جت‌انجین.
 *        — مقدار پیشین هر پست پیش از نوشتن در کانال import لاگ؛ آخرین
 *          درون‌ریزی برگشت‌پذیر. هرس و «پاک‌کردن لاگ» ردیف‌های آن را نگه
 *          می‌دارند. هیچ جدول و نوع پست تازه‌ای نیست.
 *
 * 4.11.0 — SPRINT-4.4 فاز ۲. هسته پروژۀ چهارم workspace شد (P5-D014).
 *
 *        — نسخه یکی شد: سربرگ 4.10.0، ثابت 4.8.0 و جایگزینِ برون‌بری لاگ
